package com.pulsefit.memberservice;
import com.pulsefit.memberservice.entity.Member; import com.pulsefit.memberservice.repo.MemberRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(MemberRepository r){return args->{if(r.count()==0){r.save(make("Rahul","Kumar","rahul@example.com","9876543210","MALE","1998-04-12","Hyderabad Central"));r.save(make("Priya","Sharma","priya@example.com","9876543211","FEMALE","1999-08-20","Vijayawada"));r.save(make("Arjun","Reddy","arjun@example.com","9876543212","MALE","1997-11-05","Hyderabad Central"));r.save(make("Sneha","Patel","sneha@example.com","9876543213","FEMALE","2000-02-15","Bengaluru North"));}};} private Member make(String a,String b,String c,String d,String e,String f,String g){Member m=new Member();m.firstName=a;m.lastName=b;m.email=c;m.phone=d;m.gender=e;m.dateOfBirth=f;m.facility=g;m.membershipStatus="ACTIVE";return m;} }
